"use strict";(self.webpackChunkailmanac=self.webpackChunkailmanac||[]).push([["2841"],{15996(e,n,i){i.r(n),i.d(n,{metadata:()=>r,default:()=>h,frontMatter:()=>a,contentTitle:()=>l,toc:()=>o,assets:()=>d});var r=JSON.parse('{"id":"playbooks/evaluating-agents","title":"Bewertung deines KI-Agenten","description":"Bewerte Agenten anhand der Trajektorie, nicht nur der finalen Antwort \u2014 Golden Set, geschichtete Metriken, vertrauensw\xfcrdiger LLM-as-Judge, CI-Gate.","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/playbooks/evaluating-agents.mdx","sourceDirName":"playbooks","slug":"/playbooks/evaluating-agents","permalink":"/ailmanac/de/docs/playbooks/evaluating-agents","draft":false,"unlisted":false,"editUrl":"https://github.com/derob98/ailmanac/tree/main/docs/playbooks/evaluating-agents.mdx","tags":[],"version":"current","sidebarPosition":9,"frontMatter":{"sidebar_position":9,"title":"Bewertung deines KI-Agenten","description":"Bewerte Agenten anhand der Trajektorie, nicht nur der finalen Antwort \u2014 Golden Set, geschichtete Metriken, vertrauensw\xfcrdiger LLM-as-Judge, CI-Gate."},"sidebar":"docs","previous":{"title":"Barrierefreiheit: Claude als Hilfsmittel","permalink":"/ailmanac/de/docs/playbooks/accessibility"},"next":{"title":"Schritt-f\xfcr-Schritt-Anleitungen","permalink":"/ailmanac/de/docs/walkthroughs"}}'),t=i(74848),s=i(28453);let a={sidebar_position:9,title:"Bewertung deines KI-Agenten",description:"Bewerte Agenten anhand der Trajektorie, nicht nur der finalen Antwort \u2014 Golden Set, geschichtete Metriken, vertrauensw\xfcrdiger LLM-as-Judge, CI-Gate."},l,d={},o=[{value:"Warum Agenten eigene Evals brauchen",id:"warum-agenten-eigene-evals-brauchen",level:2},{value:"Die vier Eval-Ebenen",id:"die-vier-eval-ebenen",level:2},{value:"Metriken, die Wert vorhersagen",id:"metriken-die-wert-vorhersagen",level:2},{value:"Das Golden Set aufbauen",id:"das-golden-set-aufbauen",level:2},{value:"LLM-as-Judge \u2014 g\xfcnstig, schnell, aber kalibrieren",id:"llm-as-judge--g\xfcnstig-schnell-aber-kalibrieren",level:2},{value:"CI-Gate: die schlechte \xc4nderung stoppen, bevor sie ausgeliefert wird",id:"ci-gate-die-schlechte-\xe4nderung-stoppen-bevor-sie-ausgeliefert-wird",level:2},{value:"Pr\xfcfe dich selbst",id:"pr\xfcfe-dich-selbst",level:2},{value:"Weiter",id:"weiter",level:2}];function u(e){let n={a:"a",code:"code",em:"em",h2:"h2",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,s.R)(),...e.components},{Callout:i,Flashcards:r,LevelBadge:a,PromptCard:l,Quiz:d,Steps:o,VerifyNote:u}=n;return i||c("Callout",!0),r||c("Flashcards",!0),a||c("LevelBadge",!0),l||c("PromptCard",!0),d||c("Quiz",!0),o||c("Steps",!0),u||c("VerifyNote",!0),(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(a,{level:"advanced"}),"\n",(0,t.jsx)(u,{lastVerified:"2026-07-24",source:"https://platform.claude.com/docs/en/test-and-evaluate/develop-tests",children:(0,t.jsx)(n.p,{children:"Der Evaluationsleitfaden von Anthropic ist die Quelle der Wahrheit f\xfcr die Methodik (SMART-Kriterien, Exact-Match, LLM-bewertete Likert-/Bin\xe4rskalen). Die Bewertung von Agenten-Trajektorien ist eine junge Disziplin \u2014 behandle Framework-Namen als illustrativ und \xfcberpr\xfcfe APIs in der jeweiligen Anbieter-Dokumentation."})}),"\n",(0,t.jsx)(i,{type:"objectives",items:["Verstehen, warum Agenten-Evals sich von Prompt-Evals unterscheiden \u2014 die Trajektorie z\xe4hlt, nicht nur die finale Antwort","Ein Golden Set aus 20\u2013100 realen F\xe4llen mit klaren Bestehenskriterien aufbauen","Vier Ebenen bewerten: Tool-Call-Korrektheit, Trajektorienqualit\xe4t, Aufgabenerfolg, Produktions-Drift","LLM-as-Judge sicher einsetzen: erst Rubrik, gegen Menschen kalibrieren, Urteile stichprobenartig pr\xfcfen","Eine Eval ausliefern, die in CI l\xe4uft und eine schlechte \xc4nderung stoppt, bevor sie Nutzer erreicht"]}),"\n",(0,t.jsxs)(n.p,{children:["Eine ",(0,t.jsx)(n.strong,{children:"Agenten-Eval"}),' beantwortet eine schwierigere Frage als "hat der Prompt die richtigen W\xf6rter zur\xfcckgegeben?" Sie fragt: ',(0,t.jsx)(n.em,{children:"hat ein Modell, das in einer Schleife l\xe4uft, die richtigen Tools in der richtigen Reihenfolge mit den richtigen Argumenten gew\xe4hlt, das richtige Ergebnis erreicht \u2014 und dabei Budget- und Sicherheitsgrenzen eingehalten?"})]}),"\n",(0,t.jsx)(n.p,{children:'\xdcberspringe diesen Schritt und du lieferst einen "hilfreichen" Agenten aus, der jedes Mal still regressiert, wenn du am System-Prompt drehst.'}),"\n",(0,t.jsx)(n.h2,{id:"warum-agenten-eigene-evals-brauchen",children:"Warum Agenten eigene Evals brauchen"}),"\n",(0,t.jsxs)(n.p,{children:["Eine Single-Prompt-Eval bewertet eine Eingabe \u2192 eine Ausgabe. Ein Agent erzeugt eine ",(0,t.jsx)(n.strong,{children:"Trajektorie"}),": eine Kette aus Reasoning, Tool-Aufrufen, Zwischenbeobachtungen und \xdcberarbeitungen \xfcber viele Turns hinweg. Zwei Fehlerarten machen das schwierig:"]}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Richtige Antwort, falscher Pfad."})," Der Agent stolpert durch verschwenderische Schleifen, unsichere Aktionen oder Zufallstreffer zur richtigen Ausgabe. Evals, die nur die finale Antwort pr\xfcfen, markieren das als Pass; die Produktion nicht."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Falsche Antwort, plausibler Pfad."})," Jeder Schritt sieht isoliert vern\xfcnftig aus, aber der Agent hat ein Tool missbraucht, eine Randbedingung ignoriert oder ein Zwischen-Faktum halluziniert. Du musst das Trace anschauen, nicht nur die Antwort."]}),"\n"]}),"\n",(0,t.jsx)(n.mermaid,{value:"flowchart LR\n  I[Input] --\x3e A[Agent loop]\n  A --\x3e T1[tool_call 1]\n  T1 --\x3e T2[tool_call 2]\n  T2 --\x3e T3[...]\n  T3 --\x3e O[Final output]\n  O --\x3e J{Eval}\n  J --\x3e|Output only| M[Misses path bugs]\n  J --\x3e|+ Trajectory| G[Catches wandering, wrong tool, unsafe step]"}),"\n",(0,t.jsx)(n.h2,{id:"die-vier-eval-ebenen",children:"Die vier Eval-Ebenen"}),"\n",(0,t.jsx)(n.p,{children:"Schichte sie g\xfcnstig-zuerst, damit eine schlechte \xc4nderung schnell scheitert, ohne auf teure Grader zu warten."}),"\n",(0,t.jsx)(o,{items:[{title:"Ebene 1 \u2014 Tool-Call-Korrektheit (deterministisch)",body:"F\xfcr jeden erwarteten Schritt pr\xfcfen: stimmt der Tool-Name, sind die erforderlichen Parameter vorhanden, validieren die Typen? Reiner Code, Millisekunden, kein Modell n\xf6tig. F\xe4ngt 'hat search aufgerufen, obwohl write_file dran gewesen w\xe4re' ab, bevor irgendetwas anderes l\xe4uft."},{title:"Ebene 2 \u2014 Trajektorienqualit\xe4t (Rubrik + LLM-Judge)",body:"Bewerte das gesamte Trace: hat der Agent einen sinnvollen Weg genommen, oder ist er umhergewandert, in Schleifen gelandet oder zur\xfcckgesprungen? Anzahl der Schritte vs. Minimum, redundante Aufrufe, Retries nach Tool-Fehlern, ob er gestoppt hat, als er fertig war. Nutze hier einen LLM-Judge mit expliziter Rubrik."},{title:"Ebene 3 \u2014 Aufgabenerfolg (End-to-End)",body:"Wurde das Ziel erreicht? Deterministisch wo m\xf6glich (Schema g\xfcltig, Datei geschrieben, Test besteht), LLM-bewertet wo unscharf (Zusammenfassung treu, Antwort hilfreich). Das ist deine Headline-Zahl."},{title:"Ebene 4 \u2014 Produktions-Drift & Sicherheit",body:"In der Produktion echte Traces sampeln und einen Ausschnitt nachbewerten. Beobachte die Interventionsrate (wie oft musste ein Mensch eingreifen), die Refusal-Rate und die Kosten pro erfolgreicher Aufgabe. Verschieben sich diese, hat sich dein Modell, dein Tool oder dein Input unter dir ver\xe4ndert."}]}),"\n",(0,t.jsx)(n.h2,{id:"metriken-die-wert-vorhersagen",children:"Metriken, die Wert vorhersagen"}),"\n",(0,t.jsx)(n.p,{children:"Nicht jede Metrik geh\xf6rt aufs Dashboard. Diese f\xfcnf treiben 2026 die Ausliefer-Entscheidungen:"}),"\n",(0,t.jsxs)(n.table,{children:[(0,t.jsx)(n.thead,{children:(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.th,{children:"Metrik"}),(0,t.jsx)(n.th,{children:"Was sie misst"}),(0,t.jsx)(n.th,{children:"Warum sie z\xe4hlt"})]})}),(0,t.jsxs)(n.tbody,{children:[(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:(0,t.jsx)(n.strong,{children:"Aufgabenerfolgsrate"})}),(0,t.jsx)(n.td,{children:"% der Golden-Set-F\xe4lle, die der Agent korrekt abschlie\xdft"}),(0,t.jsx)(n.td,{children:"Die Headline. Alles andere ist Diagnostik."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:(0,t.jsx)(n.strong,{children:"Kosten pro erfolgreicher Aufgabe"})}),(0,t.jsx)(n.td,{children:"$ / bestandener Fall (Tokens rein + raus, Tool-Kosten)"}),(0,t.jsx)(n.td,{children:"Erfolg zum 10-fachen Preis ist eine Regression."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:(0,t.jsx)(n.strong,{children:"Latenz (p50 / p95)"})}),(0,t.jsx)(n.td,{children:"Wanduhr-Zeit pro Aufgabe, inklusive Tail"}),(0,t.jsx)(n.td,{children:"p95 ist, was echte Nutzer sp\xfcren \u2014 Durchschnitte l\xfcgen."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:(0,t.jsx)(n.strong,{children:"Tool-Call-Genauigkeit"})}),(0,t.jsx)(n.td,{children:"% der erwarteten Tool-Aufrufe mit korrektem Namen + Args"}),(0,t.jsx)(n.td,{children:"Sagt Trajektorienqualit\xe4t voraus; g\xfcnstig zu berechnen."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:(0,t.jsx)(n.strong,{children:"Interventionsrate"})}),(0,t.jsx)(n.td,{children:"% der Aufgaben, bei denen ein Mensch in der Produktion \xfcbernehmen musste"}),(0,t.jsx)(n.td,{children:"Die Autonomie-Zahl. Steigend = Vertrauen sinkt."})]})]})]}),"\n",(0,t.jsx)(n.p,{children:"Verfolge sie zusammen \u2014 eine, die sich ohne die anderen bewegt, ist meist ein Fr\xfchsignal, kein Rauschen."}),"\n",(0,t.jsx)(n.h2,{id:"das-golden-set-aufbauen",children:"Das Golden Set aufbauen"}),"\n",(0,t.jsx)(o,{items:[{title:"Reale Eingaben minen",body:"Ziehe 20\u2013100 Aufgaben aus tats\xe4chlicher Nutzung (Logs, Support-Tickets, Nutzeranfragen). Decke den h\xe4ufigen einfachen Pfad, die knifflige Mitte und die Edge Cases ab, die dich schon einmal gebissen haben."},{title:"Bestehenskriterien pro Fall schreiben",body:"F\xfcr jeden: Wie sieht 'fertig' aus? Exakte erwartete Ausgabe, geforderte Fakten, g\xfcltiges JSON-Schema, Dateien, die existieren m\xfcssen, oder eine Rubrik f\xfcr unscharfe F\xe4lle. Kannst du das Kriterium nicht formulieren, ist der Fall unbrauchbar \u2014 streiche oder pr\xe4zisiere ihn."},{title:"Die ideale Trajektorie annotieren",body:"Skizziere f\xfcr einen Teilbereich die Tool-Sequenz, die ein guter Agent nehmen w\xfcrde. Genau dagegen pr\xfcft Ebene 1."},{title:"Einfrieren, versionieren",body:"Commite das Set in dein Repo. Bearbeite nie einen Fall an Ort und Stelle \u2014 lege v2 neben v1, damit die Score-Historie vergleichbar bleibt."},{title:"Aus Fehlern wachsen lassen",body:"Jeder Prod-Bug wird zu einem neuen Eval-Fall, bevor du ihn behebst. So bleibt das Set vorhersagekr\xe4ftig, statt zu verfallen."}]}),"\n",(0,t.jsx)(n.h2,{id:"llm-as-judge--g\xfcnstig-schnell-aber-kalibrieren",children:"LLM-as-Judge \u2014 g\xfcnstig, schnell, aber kalibrieren"}),"\n",(0,t.jsxs)(n.p,{children:["Unscharfe Ausgaben von Hand zu bewerten skaliert nicht. Ein f\xe4higes Modell, das gegen eine explizite Rubrik liest, schon \u2014 Anthropics eigener ",(0,t.jsx)(n.a,{href:"https://platform.claude.com/docs/en/test-and-evaluate/develop-tests",children:"Eval-Methodik-Leitfaden"})," empfiehlt dieses Muster f\xfcr Ton, Treue, Hilfsbereitschaft und Sicherheit."]}),"\n",(0,t.jsx)(n.p,{children:"Judges haben gut dokumentierte Biases: Sie bevorzugen l\xe4ngere Antworten, die erste gezeigte Option und Ausgaben, die ihre eigene Ausdrucksweise widerspiegeln. Drei Gewohnheiten halten sie ehrlich:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Rubrik, keine Bauchgef\xfchle."}),' "Bewerte Hilfsbereitschaft 1\u20135" ist nutzlos. Verankere jeden Punkt auf der Skala an beobachtbarem Verhalten.']}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Kalibriere gegen ein von Menschen gelabeltes Sample."})," Lass Menschen 30\u201350 F\xe4lle bewerten; miss die Judge-vs-Mensch-\xdcbereinstimmung (Ziel: Cohens \u03BA \u2265 0.6). Weicht er ab, versch\xe4rfe die Rubrik."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Nutze ein anderes Modell als Judge."})," Mit demselben Modell zu bewerten, das die Ausgabe erzeugt hat, verzerrt in beide Richtungen."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Pr\xfcfe Urteile w\xf6chentlich stichprobenartig."})," Lies 10 zuf\xe4llige Judge-Scores und deren Begr\xfcndungen. Das ist der g\xfcnstigste Weg, Drift zu erkennen."]}),"\n"]}),"\n",(0,t.jsx)(l,{title:"LLM-as-Judge-Rubrik-Vorlage",children:`You are grading an AI assistant's response against a rubric. Be strict. Cite exact evidence from the response.

<task>{task}</task>
<response>{response}</response>

Rubric (rate 1\u{2013}5 per dimension):
- Task completion: 1 = ignored task; 3 = partial; 5 = fully done, no gaps.
- Faithfulness: 1 = contains false claims; 3 = mostly grounded, one soft claim; 5 = every claim traceable to input/tools.
- Efficiency: 1 = wandered/looped; 3 = extra steps; 5 = minimum viable path.

Output JSON only:
{"task_completion": N, "faithfulness": N, "efficiency": N, "evidence": "<quote>", "verdict": "pass"|"fail"}`}),"\n",(0,t.jsx)(l,{title:"Trajektorien-Review-Prompt (Ebene 2)",children:`You are auditing an AI agent's tool-call trajectory. The goal was: {goal}
Expected minimum steps: {n_min}

<trajectory>
{list of tool_name(args) -> result, in order}
</trajectory>

Answer in JSON:
{"steps_taken": N, "wasted_steps": N, "wrong_tool_calls": [<indices>], "unsafe_actions": [<indices>], "verdict": "pass"|"fail", "reason": "<one sentence>"}`}),"\n",(0,t.jsx)(l,{title:"Adversarialer Fallgenerator (Set wachsen lassen)",children:`Generate 5 new eval cases that are likely to break an agent whose current failures cluster around: {failure_pattern}.

For each case give: input, expected output OR pass criterion, ideal tool sequence, and why this case is hard.

Return YAML.`}),"\n",(0,t.jsx)(n.h2,{id:"ci-gate-die-schlechte-\xe4nderung-stoppen-bevor-sie-ausgeliefert-wird",children:"CI-Gate: die schlechte \xc4nderung stoppen, bevor sie ausgeliefert wird"}),"\n",(0,t.jsx)(n.p,{children:"Die Eval zahlt sich erst aus, wenn sie Regressionen automatisch blockiert. Verdrahte sie in CI als Check bei jeder Prompt-/Modell-/Tool-\xc4nderung:"}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-python",children:'# tests/eval_gate.py \u2014 runs on every PR\nimport json, sys\nfrom anthropic import Anthropic\nfrom my_agent import run_agent\n\nclient = Anthropic()\ngolden = json.load(open("evals/golden.v3.json"))\n\nresults = []\nfor case in golden:\n    trace = run_agent(case["input"])\n    layer1 = tool_calls_match(trace, case["expected_tools"])   # deterministic\n    layer3 = judge(client, case, trace.final_output)           # LLM rubric\n    results.append({"id": case["id"], "layer1": layer1, "layer3": layer3["verdict"]})\n\npass_rate = sum(r["layer3"] == "pass" for r in results) / len(results)\ntool_acc  = sum(r["layer1"] for r in results) / len(results)\n\n# Gates \u2014 tighten over time\nassert pass_rate >= 0.85, f"Task success dropped to {pass_rate:.0%}"\nassert tool_acc  >= 0.90, f"Tool-call accuracy dropped to {tool_acc:.0%}"\nprint(f"PASS: task={pass_rate:.0%} tools={tool_acc:.0%}")\n'})}),"\n",(0,t.jsx)(n.p,{children:"Speichere die Scores pro Lauf, damit du den Trend charten kannst. Ein Abfall von 3+ Punkten zwischen Merges ist eine echte Regression, kein Rauschen."}),"\n",(0,t.jsx)(i,{type:"warning",title:"Anti-Patterns, die Evals unterliefern lassen",items:["Nur die finale Antwort bewerten \u2014 verpasst jeden Trajektorien-Bug. Bewerte auch Ebenen 1 und 2.","Statisches Golden Set \u2014 w\xe4chst es nicht mit jedem Prod-Fehler mit, sagt es Prod nicht mehr voraus. Reserviere monatlich Zeit.","Gleiches Modell als Agent und Judge \u2014 Bias in beide Richtungen. Rotiere f\xfcr die Bewertung zu einem anderen Modell.","Keine Kosten oder Latenz im Gate \u2014 ein Prompt-Tweak, der 8 Tool-Aufrufe hinzuf\xfcgt, kann die Eval 'bestehen' und dabei die Rechnung verzehnfachen.","Nur-Bauchgef\xfchl-Scoring \u2014 'f\xfchlt sich besser an' ist keine Metrik. Wenn du zwei Zahlen nicht diffen kannst, kannst du nicht souver\xe4n ausliefern."]}),"\n",(0,t.jsx)(i,{type:"takeaways",items:["Agenten produzieren Trajektorien, nicht Antworten \u2014 bewerte den Weg, nicht nur das Ergebnis","Schichte g\xfcnstig-zuerst: Tool-Call-Korrektheit \u2192 Trajektorienqualit\xe4t \u2192 Aufgabenerfolg \u2192 Produktions-Drift","Die f\xfcnf Metriken, die Ausliefer-Entscheidungen tragen: Aufgabenerfolgsrate, Kosten pro Erfolg, p50/p95-Latenz, Tool-Call-Genauigkeit, Interventionsrate","LLM-as-Judge skaliert, aber nur mit expliziter Rubrik, einem anderen Modell und Kalibrierung gegen menschliche Labels","Ein Golden Set, das nicht aus Prod-Fehlern w\xe4chst, sagt Prod nicht mehr voraus \u2014 lass es monatlich wachsen","Verdrahte die Eval als hartes Gate in CI \u2014 der Check, der eine Regression f\xe4ngt, bevor Nutzer es tun"]}),"\n",(0,t.jsx)(n.h2,{id:"pr\xfcfe-dich-selbst",children:"Pr\xfcfe dich selbst"}),"\n",(0,t.jsx)(d,{title:"Pr\xfcfe dich selbst",questions:[{q:"Warum brauchen Agenten Trajektorien-Evals und nicht nur Final-Antwort-Evals?",options:["Final-Antwort-Evals sind zu langsam, um in CI zu laufen","Ein Agent kann via Umherwandern oder unsicherer Schritte zur richtigen Antwort kommen (richtige Antwort, falscher Pfad) \u2014 und einen plausibel aussehenden Pfad zu einer falschen Antwort produzieren","Trajektorien-Evals sind die einzige Art, die LLM-as-Judge unterst\xfctzt","Final-Antwort-Evals funktionieren nur f\xfcr Klassifikationsaufgaben"],answer:1,explain:"Zwei Fehlermuster verstecken sich vor reinen Output-Scores: richtige Antwort \xfcber einen schlechten Pfad (als Pass markiert, wird in Prod regressieren) und falsche Antwort \xfcber einen plausiblen Pfad (scheitert lautlos). Du musst die Trajektorie ebenso wie das Ergebnis bewerten."},{q:"Du schichtest deine Evals. Welche Reihenfolge ist g\xfcnstig-zu-teuer und korrekt?",options:["LLM-bewerteter Aufgabenerfolg \u2192 deterministische Tool-Call-Checks \u2192 Produktions-Drift \u2192 Trajektorien-Rubrik","Deterministische Tool-Call-Korrektheit \u2192 Trajektorienqualit\xe4t (LLM-Judge) \u2192 Aufgabenerfolg \u2192 Produktions-Drift","Produktions-Drift \u2192 Aufgabenerfolg \u2192 Trajektorien-Rubrik \u2192 Tool-Call-Checks","Trajektorien-Rubrik \u2192 Aufgabenerfolg \u2192 Tool-Call-Checks \u2192 Produktions-Drift"],answer:1,explain:"Ebene 1 (deterministische Tool-Call-Checks) l\xe4uft in Millisekunden ohne Modell und stoppt schlechte \xc4nderungen schnell. Dann LLM-bewertete Trajektorien- und Aufgabenerfolg-Ebenen, dann Produktions-Drift-Monitoring."},{q:"Welches Paar Gewohnheiten h\xe4lt LLM-as-Judge tats\xe4chlich langfristig vertrauensw\xfcrdig?",options:["Mit demselben Modell wie der Agent bewerten und die Rubrik bei jedem Lauf neu schreiben","Eine Rubrik mit beobachtbaren Ankern verwenden und den Judge gegen ein von Menschen gelabeltes Sample kalibrieren","Bauchgef\xfchl-Prompts bevorzugen, um nicht zu \xfcberspezifizieren, und Urteile nie stichprobenartig pr\xfcfen","Immer das gr\xf6\xdfte verf\xfcgbare Modell als Judge nutzen, keine Kalibrierung n\xf6tig"],answer:1,explain:"Verankerte Rubriken nehmen dem Judge die Freiheit, Kriterien zu erfinden, und menschliche Kalibrierung (Cohens \u03BA \u2265 0.6 ist ein \xfcblicher Zielwert) beweist, dass der Judge mit deiner Grundwahrheit \xfcbereinstimmt. Ein anderes Modell zu nutzen und w\xf6chentlich stichprobenartig zu pr\xfcfen, vervollst\xe4ndigt das Bild."},{q:"Dein CI-Gate besteht bei der Aufgabenerfolgsrate, aber Latenz und Kosten pro Aufgabe haben sich verdoppelt. Was ist die richtige Entscheidung?",options:["Auslieferung \u2014 Aufgabenerfolg ist die Headline-Metrik","Gate scheitern lassen: die f\xfcnf Ausliefer-Metriken bewegen sich zusammen, und eine 2\xd7-\xc4nderung bei Kosten/Latenz ist eine Regression, auch wenn die Pass-Rate hielt","Eval neu laufen lassen \u2014 die Zahlen m\xfcssen Rauschen sein","Die Pass-Rate-Schwelle lockern, um die Auslieferung zu rechtfertigen"],answer:1,explain:"Die f\xfcnf Metriken tragen gemeinsam Ausliefer-Entscheidungen. Ein Prompt-Tweak, der die Pass-Rate flach h\xe4lt, w\xe4hrend er Kosten oder Latenz verdoppelt, ist genau die Art Fehler, f\xfcr die das Gate existiert \u2014 Rechnungs- und UX-Regressionen treffen Nutzer genauso hart wie Genauigkeitseinbr\xfcche."}]}),"\n",(0,t.jsx)(r,{cards:[{front:"Trajektorie (in Agenten-Evals)",back:"Die vollst\xe4ndige, geordnete Kette aus Tool-Aufrufen, Argumenten, Beobachtungen und Reasoning-Schritten, die ein Agent \xfcber eine Aufgabe hinweg unternimmt \u2014 das, was du zus\xe4tzlich zur finalen Ausgabe bewertest."},{front:"Golden Set",back:"Eine eingefrorene, versionierte Sammlung von 20\u2013100 realen Aufgaben mit expliziten Bestehenskriterien (und f\xfcr einen Teil idealen Trajektorien), gegen die jede Prompt-/Modell-/Tool-\xc4nderung bewertet wird."},{front:"Tool-Call-Genauigkeit",back:"% der erwarteten Tool-Aufrufe, bei denen der Name stimmt und die erforderlichen Parameter validieren. Deterministisch, g\xfcnstig und ein starker Fr\xfchindikator f\xfcr Trajektorienqualit\xe4t."},{front:"LLM-as-Judge",back:"Bewertungsmuster, bei dem ein (anderes) f\xe4higes Modell Ausgaben gegen eine explizite Rubrik bewertet. Schnell und skalierbar, muss aber gegen menschliche Labels kalibriert werden, um vertrauensw\xfcrdig zu sein."},{front:"Interventionsrate",back:"% der Produktionsaufgaben, bei denen ein Mensch \xfcbernehmen musste. Steigende Interventionsrate = sinkende Autonomie, selbst wenn die Offline-Scores gut aussehen."},{front:"Kosten pro erfolgreicher Aufgabe",back:"Gesamt-Token- + Tool-Kosten geteilt durch die Anzahl der Aufgaben, die der Agent korrekt abgeschlossen hat. F\xe4ngt Regressionen ab, bei denen 'funktioniert noch' das '10\xd7 teurer' verbirgt."},{front:"CI-Eval-Gate",back:"Ein automatisierter Check bei jedem PR, der das Golden Set ausf\xfchrt und den Build unterhalb von Schwellen (z. B. Pass-Rate < 85%, Tool-Genauigkeit < 90%) hart scheitern l\xe4sst. Blockiert stille Regressionen vor dem Merge."}]}),"\n",(0,t.jsx)(n.h2,{id:"weiter",children:"Weiter"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.a,{href:"/docs/api/building-agents",children:"Agenten auf der API bauen"})," \xb7 ",(0,t.jsx)(n.a,{href:"/docs/foundations/evals",children:"Evals (Grundlagen)"})]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.a,{href:"/docs/security/securing-agents",children:"Agenten & Tools absichern"})," \xb7 ",(0,t.jsx)(n.a,{href:"/docs/foundations/hallucinations",children:"Halluzinationen und wie man sie reduziert"})]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.a,{href:"/docs/claude-code/headless-and-agent-sdk",children:"Headless & Agent SDK"})," \xb7 ",(0,t.jsx)(n.a,{href:"/docs/api/managed-agents",children:"Managed Agents"})]}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(u,{...e})}):u(e)}function c(e,n){throw Error("Expected "+(n?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}},28453(e,n,i){i.d(n,{R:()=>a,x:()=>l});var r=i(96540);let t={},s=r.createContext(t);function a(e){let n=r.useContext(s);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}}}]);